import { copyFile, readFile, writeFile } from 'node:fs/promises';

const root = new URL('../../', import.meta.url);
const css = await readFile(new URL('marp/themes/line-seed.source.css', root), 'utf8');
const header = `/* @theme hkaomua */
/* Generated by npm run theme:pages. Edit marp/themes/line-seed.source.css. */
@import url('https://fonts.googleapis.com/css2?family=LINE+Seed+JP:wght@400;700;800&display=swap');
`;
await writeFile(new URL('docs/hkaomua.css', root),
  header + css);
await copyFile(new URL('fonts/OFL.txt', root), new URL('docs/OFL.txt', root));
await copyFile(new URL('LICENSE', root), new URL('docs/LICENSE', root));
console.log('Generated docs/hkaomua.css for GitHub Pages.');
